window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a23d26cd0def155b"]={"versions": [{"id": "FIG-a23d26cd0def155b", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-basiertes Methodik-Diagramm (Aktivitätszerlegung / Activity Decomposition) im Kontext der AUTOSAR Classic Platform Methodology. Das Diagramm spezifiziert die strukturelle Zerlegung der übergeordneten Verbundaktivität (Composite Task) „Do Link Time Configuration“ in ihre konstituierenden Teilaktivitäten (Sub-Tasks) innerhalb des Link-Time-Konfigurationsansatzes.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Do Link Time Configuration</strong>: Zusammengesetzte Elternaktivität (Composite Activity), dargestellt als abgerundetes Rechteck mit integriertem Prozess- und Artefakt-Piktogramm.</li>\n<li><strong>Sub-Aktivitäten</strong> (jeweils dargestellt als Aktivitäts-Chevron/Blockpfeil nach rechts):</li>\n<li><code>Generate BSW Configuration Code</code>: Generierung des BSW-Konfigurationsquellcodes auf Basis der Link-Time-Parameter.</li>\n<li><code>Compile Unconfigured BSW</code>: Übersetzung der unkonfigurierten BSW-Quellcodedateien zu Objektcode.</li>\n<li><code>Link ECU Code during Link Time Configuration</code>: Binden der Objektdateien und Konfigurationsartefakte zur ausführbaren ECU-Binärdatei.</li>\n<li>Unbenannte/abgeschnittene Aktivität (unten rechts): Chevron-Pfeilsymbol für den Übersetzungsschritt des generierten Konfigurationscodes, dessen Beschriftung am unteren Bildrand abgeschnitten ist.</li>\n<li><strong>Beziehungen</strong>: Vier gerichtete Schachtelungsassoziationen mit nicht ausgefüllter Raute auf Seiten der Elternaktivität und der Stereotyp-Annotation <code>«nesting»</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm deklariert primär eine statische Hierarchie (Zerlegung), bildet jedoch die logische Sequenz des Link-Time-Konfigurationsablaufs ab:</p>\n<ol class=\"fig-list\">\n<li><code>Generate BSW Configuration Code</code> führt zur Erzeugung der modulspezifischen Link-Time-Konfigurationsquelldateien.</li>\n<li><code>Compile Unconfigured BSW</code> erzeugt die vorkompilierten Objektdateien der Basissoftware.</li>\n<li>Der generierte Konfigurationscode wird kompiliert (durch die vierte Teilaktivität am unteren Bildrand).</li>\n<li><code>Link ECU Code during Link Time Configuration</code> führt alle kompilierten Objekte und Konfigurationsstrukturen zusammen, löst Link-Time-Symbole auf und generiert das lauffähige ECU-Image.</li>\n</ol>\n<p class=\"fig-p\">Explizite Kontrollfluss- oder Datenflusskanten (Eingangs-/Ausgangsartefakte) sind in diesem Diagramm nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für AUTOSAR-Methodik-Werkzeuge und Prozess-Engines zur Modellierung und Automatisierung des Link-Time-Workflows. Entwickler und Integratoren müssen beachten, dass Link-Time-Konfiguration die strikte Trennung zwischen unkonfiguriertem BSW-Code und generiertem Konfigurationscode voraussetzt, um die Vorab-Kompilierung von BSW-Modulen ohne Kenntnis finaler Integrationsparameter zu ermöglichen. Die abgeschnittene Beschriftung der vierten Sub-Aktivität stellt ein Artefakt des Quell-Renderings dar; methodisch repräsentiert das Element das Kompilieren des zuvor generierten Konfigurationscodes vor dem abschließenden Linkvorgang.</p>"}, {"id": "FIG-252aa57190e32ed9", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-basiertes Methodik-Diagramm (Aktivitätszerlegung / Activity Decomposition) im Kontext der AUTOSAR Classic Platform Methodology. Das Diagramm spezifiziert die strukturelle Zerlegung der übergeordneten Verbundaktivität (Composite Task) „Do Link Time Configuration“ in ihre konstituierenden Teilaktivitäten (Sub-Tasks) innerhalb des Link-Time-Konfigurationsansatzes.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Do Link Time Configuration</strong>: Zusammengesetzte Elternaktivität (Composite Activity), dargestellt als abgerundetes Rechteck mit integriertem Prozess- und Artefakt-Piktogramm.</li>\n<li><strong>Sub-Aktivitäten</strong> (jeweils dargestellt als Aktivitäts-Chevron/Blockpfeil nach rechts):</li>\n<li><code>Generate BSW Configuration Code</code>: Generierung des BSW-Konfigurationsquellcodes auf Basis der Link-Time-Parameter.</li>\n<li><code>Compile Unconfigured BSW</code>: Übersetzung der unkonfigurierten BSW-Quellcodedateien zu Objektcode.</li>\n<li><code>Link ECU Code during Link Time Configuration</code>: Binden der Objektdateien und Konfigurationsartefakte zur ausführbaren ECU-Binärdatei.</li>\n<li>Unbenannte/abgeschnittene Aktivität (unten rechts): Chevron-Pfeilsymbol für den Übersetzungsschritt des generierten Konfigurationscodes, dessen Beschriftung am unteren Bildrand abgeschnitten ist.</li>\n<li><strong>Beziehungen</strong>: Vier gerichtete Schachtelungsassoziationen mit nicht ausgefüllter Raute auf Seiten der Elternaktivität und der Stereotyp-Annotation <code>«nesting»</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm deklariert primär eine statische Hierarchie (Zerlegung), bildet jedoch die logische Sequenz des Link-Time-Konfigurationsablaufs ab:</p>\n<ol class=\"fig-list\">\n<li><code>Generate BSW Configuration Code</code> führt zur Erzeugung der modulspezifischen Link-Time-Konfigurationsquelldateien.</li>\n<li><code>Compile Unconfigured BSW</code> erzeugt die vorkompilierten Objektdateien der Basissoftware.</li>\n<li>Der generierte Konfigurationscode wird kompiliert (durch die vierte Teilaktivität am unteren Bildrand).</li>\n<li><code>Link ECU Code during Link Time Configuration</code> führt alle kompilierten Objekte und Konfigurationsstrukturen zusammen, löst Link-Time-Symbole auf und generiert das lauffähige ECU-Image.</li>\n</ol>\n<p class=\"fig-p\">Explizite Kontrollfluss- oder Datenflusskanten (Eingangs-/Ausgangsartefakte) sind in diesem Diagramm nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für AUTOSAR-Methodik-Werkzeuge und Prozess-Engines zur Modellierung und Automatisierung des Link-Time-Workflows. Entwickler und Integratoren müssen beachten, dass Link-Time-Konfiguration die strikte Trennung zwischen unkonfiguriertem BSW-Code und generiertem Konfigurationscode voraussetzt, um die Vorab-Kompilierung von BSW-Modulen ohne Kenntnis finaler Integrationsparameter zu ermöglichen. Die abgeschnittene Beschriftung der vierten Sub-Aktivität stellt ein Artefakt des Quell-Renderings dar; methodisch repräsentiert das Element das Kompilieren des zuvor generierten Konfigurationscodes vor dem abschließenden Linkvorgang.</p>"}], "trans": [{"from": "FIG-a23d26cd0def155b", "to": "FIG-252aa57190e32ed9", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
